-    public function canTransitionTo(self $newStatus): bool
-    {
-        return match($this) {
-            self::Pending => in_array($newStatus, [self::Processing, self::Cancelled]),
-            self::Processing => in_array($newStatus, [self::Shipped, self::Cancelled]),
