-        {
-            var response = await next();
-            sw.Stop();
-
-            logger.LogInformation(
-                "Handled {RequestName} ({RequestId}) in {ElapsedMs}ms",
-                requestName, requestId, sw.ElapsedMilliseconds);
-
-            return response;
-        }
-        catch (Exception ex)
-        {
-            sw.Stop();
-            logger.LogError(
-                ex,
-                "Error handling {RequestName} ({RequestId}) after {ElapsedMs}ms",
-                requestName, requestId, sw.ElapsedMilliseconds);
-            throw;
-        }
-    }
-}
