-### Async Image with Cache
-
-```swift
-actor ImageCacheManager {
-    static let shared = ImageCacheManager()
-
-    private var cache = NSCache<NSURL, UIImage>()
-    private var inProgress: [URL: Task<UIImage, Error>] = [:]
-
-    private init() {
-        cache.countLimit = 100
-        cache.totalCostLimit = 50 * 1024 * 1024 // 50MB
-    }
-
-    func image(for url: URL) async throws -> UIImage {
-        // Check cache
-        if let cached = cache.object(forKey: url as NSURL) {
-            return cached
-        }
-
-        // Check in-progress
-        if let task = inProgress[url] {
-            return try await task.value
-        }
-
-        // Start download
-        let task = Task<UIImage, Error> {
-            let (data, _) = try await URLSession.shared.data(from: url)
-            guard let image = UIImage(data: data) else {
-                throw ImageError.invalidData
-            }
-            return image
-        }
-
-        inProgress[url] = task
-
-        do {
-            let image = try await task.value
-            cache.setObject(image, forKey: url as NSURL, cost: image.pngData()?.count ?? 0)
-            inProgress[url] = nil
-            return image
-        } catch {
-            inProgress[url] = nil
-            throw error
-        }
-    }
-
-    func clearCache() {
-        cache.removeAllObjects()
-    }
-}
-
-enum ImageError: Error {
-    case invalidData
-}
-
-struct CachedAsyncImage: View {
-    let url: URL?
-    var placeholder: Image = Image(systemName: "photo")
-
-    @State private var image: UIImage?
-    @State private var isLoading = false
-
-    var body: some View {
-        Group {
-            if let image = image {
-                Image(uiImage: image)
-                    .resizable()
-                    .aspectRatio(contentMode: .fill)
-            } else if isLoading {
-                ProgressView()
-            } else {
-                placeholder
-                    .resizable()
-                    .aspectRatio(contentMode: .fit)
-                    .foregroundColor(.gray)
-            }
-        }
-        .task(id: url) {
-            guard let url = url else { return }
-            isLoading = true
-            defer { isLoading = false }
-
-            do {
-                image = try await ImageCacheManager.shared.image(for: url)
-            } catch {
-                image = nil
-            }
-        }
-    }
-}
