-        };
-
-        var totalCount = await query.CountAsync(ct);
-
-        var items = await query
-            .Skip((request.Page - 1) * request.PageSize)
-            .Take(request.PageSize)
-            .Select(u => new UserDto(u.Id, u.Name, u.Email, u.Role, u.CreatedAt))
