-        _dep = dep;
-    }
-    
-    public void DoWork() => _dep.Execute();
-}
-
-// After
-public class Service(IDependency dep)
-{
-    public void DoWork() => dep.Execute();
-}
-```
-
-### From Object Initializers to Collection Expressions
-
-```csharp
-// Before
-var list = new List<int> { 1, 2, 3 };
-var array = new int[] { 1, 2, 3 };
-
-// After
-List<int> list = [1, 2, 3];
-int[] array = [1, 2, 3];
-```
